-- Project Mercury: GitHub OAuth/App accounts, explicit repository grants and sync state.
create table public.github_accounts(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,auth_type text not null check(auth_type in('oauth','app')),github_user_id bigint,login text not null,avatar_url text,token_ciphertext text,refresh_token_ciphertext text,token_expires_at timestamptz,status text not null default 'connected' check(status in('connected','degraded','reauthorization_required','revoked','disconnected')),scopes text[] not null default '{}',rate_limit integer,rate_remaining integer,rate_reset_at timestamptz,last_health_at timestamptz,last_refresh_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,auth_type,github_user_id));
create table public.github_installations(id bigint primary key,account_id uuid not null references public.github_accounts(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,organization_id bigint,organization_login text,repository_selection text not null check(repository_selection in('all','selected')),permissions jsonb not null default '{}',events text[] not null default '{}',suspended_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.github_repositories(id bigint primary key,owner_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null references public.github_accounts(id) on delete cascade,installation_id bigint references public.github_installations(id) on delete cascade,full_name text not null,organization_login text,visibility text not null check(visibility in('public','private','internal')),default_branch text not null,permissions jsonb not null default '{}',explicitly_granted boolean not null default false,archived boolean not null default false,last_sync_at timestamptz,last_webhook_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,full_name));
create table public.github_repository_branches(repository_id bigint not null references public.github_repositories(id) on delete cascade,name text not null,head_sha text not null,protected boolean not null default false,last_sync_at timestamptz not null default now(),primary key(repository_id,name));
create table public.github_webhooks(id bigint primary key,owner_id uuid not null references auth.users(id) on delete cascade,repository_id bigint references public.github_repositories(id) on delete cascade,installation_id bigint references public.github_installations(id) on delete cascade,active boolean not null default true,events text[] not null default '{}',last_delivery_id text,last_delivery_at timestamptz,last_status text,created_at timestamptz not null default now());
create table public.github_tool_audit(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null references public.github_accounts(id),repository_id bigint references public.github_repositories(id),tool text not null,source_type text not null check(source_type in('chat','work')),source_id text,success boolean not null,approval_id uuid references public.agent_approvals(id),redacted_metadata jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.github_accounts enable row level security;alter table public.github_installations enable row level security;alter table public.github_repositories enable row level security;alter table public.github_repository_branches enable row level security;alter table public.github_webhooks enable row level security;alter table public.github_tool_audit enable row level security;
create policy "Owners read GitHub accounts" on public.github_accounts for select using(auth.uid()=owner_id);create policy "Owners read GitHub installations" on public.github_installations for select using(auth.uid()=owner_id);create policy "Owners read granted GitHub repositories" on public.github_repositories for select using(auth.uid()=owner_id and explicitly_granted and revoked_at is null);create policy "Owners read GitHub branches" on public.github_repository_branches for select using(exists(select 1 from github_repositories r where r.id=repository_id and r.owner_id=auth.uid() and r.explicitly_granted and r.revoked_at is null));create policy "Owners read GitHub webhooks" on public.github_webhooks for select using(auth.uid()=owner_id);create policy "Owners read GitHub audit" on public.github_tool_audit for select using(auth.uid()=owner_id);
create or replace function public.disconnect_github_account(p_account_id uuid,p_remove_data boolean default false) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from github_accounts where id=p_account_id and owner_id=auth.uid()) then raise exception 'GitHub account not found';end if;update github_accounts set status='disconnected',token_ciphertext=null,refresh_token_ciphertext=null,updated_at=now() where id=p_account_id;update github_repositories set explicitly_granted=false,revoked_at=now(),updated_at=now() where account_id=p_account_id;if p_remove_data then delete from github_installations where account_id=p_account_id;end if;end $$;grant execute on function public.disconnect_github_account(uuid,boolean) to authenticated;
